Note: This is a basic implementation and does not take into account many real-world factors that would affect the behavior of a pendulum, such as air resistance, the size and shape of the bob, and the stiffness of the string.

```html
<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8">
    <title>Pendulum Applet</title>
    <style>
      canvas {
        border: 1px solid black;
      }
    </style>
  </head>
  <body>
    <h1>Pendulum Applet</h1>
    <input type="number" id="initial-angle" value="45" placeholder="Initial angle (degrees)">
    <button id="release-button" onclick="release()">Release</button>
    <canvas id="canvas" width="400" height="400"></canvas>
    <script>
      let canvas = document.getElementById('canvas');
      let ctx = canvas.getContext('2d');
      let gravity = 981; // m/s^2
      let friction = 0.05; // coefficient of friction
      let initialValue = 0;
      let angle = 0;
      let velocity = 0;
      let radius = 50;
      let length = 150;
      let release = false;

      function draw() {
        canvas.width = canvas.offsetWidth;
        canvas.height = canvas.offsetHeight;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.moveTo(canvas.width / 2, canvas.height / 2);
        ctx.lineTo(canvas.width / 2 + length * Math.sin(angle), canvas.height / 2 - length * Math.cos(angle));
        ctx.stroke();
        if (!release) {
          ctx.beginPath();
          ctx.arc(canvas.width / 2, canvas.height / 2, radius, 0, 2 * Math.PI);
          ctx.fill();
        }
        angle += velocity;
        velocity -= gravity / length * Math.sin(angle) - friction * velocity;
        if (Math.abs(velocity) < 0.01) {
          release = true;
        }
      }

      function release() {
        angle = initialValue * Math.PI / 180;
        velocity = 0;
        release = false;
        draw();
      }

      function adjustInitialValue() {
        initialValue = parseInt(document.getElementById('initial-angle').value);
        if (isNaN(initialValue)) {
          initialValue = 45;
        }
      }

      setInterval(draw, 16); // 16 milliseconds per frame
      document.getElementById('initial-angle').addEventListener('input', adjustInitialValue);
    </script>
  </body>
</html>
```

